INDEX_HTML = r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>CoA Raid Intelligence</title>
<style>
:root{color-scheme:dark;--bg:#0b1020;--panel:#131b2f;--line:#2a3754;--text:#edf2ff;--muted:#9ba9c5;--accent:#7c9cff;--ok:#72d6a0;--danger:#ff7f91;--warn:#ffd37a}*{box-sizing:border-box}body{margin:0;font-family:Segoe UI,Arial,sans-serif;background:linear-gradient(140deg,#08101f,#111a31);color:var(--text)}header{padding:18px 24px;border-bottom:1px solid var(--line);background:#0a1122}h1{margin:0 0 4px}.muted{color:var(--muted)}main{max-width:1600px;margin:auto;padding:18px;display:grid;grid-template-columns:minmax(760px,1fr) 350px;gap:16px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px}.toolbar{padding:12px;display:flex;flex-wrap:wrap;gap:10px;align-items:end;border-bottom:1px solid var(--line)}label{display:grid;gap:4px;color:var(--muted);font-size:12px}select,input,button{border:1px solid var(--line);border-radius:8px;background:#0d1528;color:var(--text);padding:8px}button{background:var(--accent);color:#081020;font-weight:700;cursor:pointer}.danger{background:var(--danger)}table{width:100%;border-collapse:collapse}th,td{padding:7px;border-bottom:1px solid var(--line);text-align:left}th{color:var(--muted);font-size:12px}td input,td select{width:100%}tr.inactive{display:none}.summary{padding:14px;display:grid;gap:12px;height:max-content}.metric{padding:12px;background:#0d1528;border:1px solid var(--line);border-radius:10px}.metric strong{display:block;font-size:26px;color:var(--ok)}.errors{color:var(--danger);font-size:13px}.saved{display:grid;gap:6px}.saved button{background:#0d1528;color:var(--text);text-align:left}.status{min-height:18px;color:var(--ok);font-size:13px}.diagnostics{white-space:pre-wrap;font:12px Consolas,monospace;background:#09101e;border:1px solid var(--line);border-radius:8px;padding:9px;max-height:190px;overflow:auto;color:var(--warn)}@media(max-width:1050px){main{grid-template-columns:1fr}}
</style></head><body>
<header><h1>CoA Raid Intelligence</h1><div class="muted">Локальный конструктор рейда • без Excel • DuckDB на этом компьютере</div></header>
<main><section class="panel"><div class="toolbar">
<label>Название<input id="planName" value="Новый план"></label><label>Формат<select id="format"><option>FLEX</option><option>10</option><option selected>25</option><option>40</option></select></label><label>Размер<input id="target" type="number" min="1" max="40" value="25"></label><label>Дата<input id="raidDate" type="date"></label><label>Босс<input id="boss"></label><button id="newPlanButton">Новый</button><button id="savePlanButton">Сохранить</button><button id="deletePlanButton" class="danger">Удалить</button><span class="status" id="status"></span>
</div><div style="overflow:auto;max-height:calc(100vh - 175px)"><table><thead><tr><th>#</th><th>Игрок</th><th>Класс</th><th>Спек</th><th>Роль</th><th>Lock</th></tr></thead><tbody id="slots"></tbody></table></div></section>
<aside class="panel summary"><div class="metric"><strong id="filled">0</strong><span class="muted">заполнено</span></div><div class="metric"><strong id="remaining">25</strong><span class="muted">осталось</span></div><div><b>Роли</b><div class="muted" id="roles">Нет заполненных ролей</div></div><div><b>Проверки</b><div class="errors" id="errors">Ошибок нет</div></div><div><b>Сохранённые планы</b><div class="saved" id="savedPlans"></div></div><div><b>Диагностика</b><div class="diagnostics" id="diagnostics">Готово</div></div></aside></main>
<script>
const tbody=document.getElementById('slots'),format=document.getElementById('format'),target=document.getElementById('target');let catalog={classes:[]},currentPlanId=null,timer;
for(let i=1;i<=40;i++)tbody.insertAdjacentHTML('beforeend',`<tr data-slot="${i}"><td>${i}</td><td><input class="player"></td><td><select class="class"></select></td><td><select class="spec"></select></td><td><input class="role" readonly></td><td><input class="locked" type="checkbox"></td></tr>`);
function logDiagnostic(message,data=null){const time=new Date().toLocaleTimeString();const extra=data?`\n${typeof data==='string'?data:JSON.stringify(data,null,2)}`:'';diagnostics.textContent=`[${time}] ${message}${extra}\n\n${diagnostics.textContent}`;console.log(message,data||'')}
async function apiFetch(url,options={}){logDiagnostic(`${options.method||'GET'} ${url}`);let response;try{response=await fetch(url,options)}catch(error){logDiagnostic(`Сетевая ошибка ${url}`,String(error));throw error}const requestId=response.headers.get('X-Request-ID')||'нет';let data=null;if(response.status!==204){const text=await response.text();try{data=text?JSON.parse(text):null}catch{data=text}}logDiagnostic(`${response.status} ${url} · request ${requestId}`,data);if(!response.ok){const detail=data?.detail;const message=typeof detail==='string'?detail:(detail?.message||data?.message||`HTTP ${response.status}`);const error=new Error(message);error.payload=data;error.requestId=requestId;error.status=response.status;throw error}return data}
function classOptions(value=''){return '<option value=""></option>'+catalog.classes.map(c=>`<option value="${c.code}" ${c.code===value?'selected':''}>${c.name}</option>`).join('')}
function syncSpecs(row,classCode='',specCode=''){const cls=catalog.classes.find(c=>c.code===classCode);row.querySelector('.spec').innerHTML='<option value=""></option>'+(cls?.specs||[]).map(s=>`<option value="${s.code}" ${s.code===specCode?'selected':''}>${s.name}</option>`).join('');row.querySelector('.role').value=(cls?.specs||[]).find(s=>s.code===specCode)?.role||''}
function requestBody(){return{plan_id:currentPlanId,plan_name:planName.value,raid_date:raidDate.value||null,boss_id:boss.value,raid_format:format.value,target_size:Number(target.value),slots:[...tbody.rows].map(r=>({slot_no:Number(r.dataset.slot),player_name:r.querySelector('.player').value,class_code:r.querySelector('.class').value,spec_code:r.querySelector('.spec').value,role:r.querySelector('.role').value,locked:r.querySelector('.locked').checked})).filter(x=>x.player_name||x.class_code||x.spec_code||x.locked)}}
async function recalcPlan(){try{const data=await apiFetch('/api/plans/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(requestBody())});data.slots.forEach(s=>{const r=tbody.querySelector(`[data-slot="${s.slot_no}"]`);r.classList.toggle('inactive',!s.active);r.querySelector('.role').value=s.role});filled.textContent=data.filled_slots;remaining.textContent=data.remaining_slots;roles.innerHTML=Object.entries(data.role_counts).map(([k,v])=>`${k}: <b>${v}</b>`).join('<br>')||'Нет заполненных ролей';errors.innerHTML=data.validation_errors.join('<br>')||'Ошибок нет'}catch(error){errors.textContent=`${error.message} (${error.status||'network'}, request ${error.requestId||'нет'})`}}
function schedule(){clearTimeout(timer);timer=setTimeout(recalcPlan,180)}
function syncFormat(){const fixed={'10':10,'25':25,'40':40};if(fixed[format.value]){target.value=fixed[format.value];target.disabled=true}else target.disabled=false;schedule()}
async function loadCatalog(){catalog=await apiFetch('/api/catalog/class-specs');[...tbody.rows].forEach(r=>{r.querySelector('.class').innerHTML=classOptions()})}
function clearCurrentPlan(){currentPlanId=null;planName.value='Новый план';raidDate.value='';boss.value='';format.value='25';target.value=25;[...tbody.rows].forEach(r=>{r.querySelector('.player').value='';r.querySelector('.class').innerHTML=classOptions();syncSpecs(r);r.querySelector('.locked').checked=false});syncFormat();status.textContent='Новый план';logDiagnostic('Создан новый локальный план')}
async function persistCurrentPlan(){status.textContent='Сохранение...';try{const data=await apiFetch('/api/plans',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(requestBody())});currentPlanId=data.plan_id;status.textContent=`Сохранено: ${data.plan_id.slice(0,8)}`;await refreshSavedPlans()}catch(error){status.textContent=`Ошибка: ${error.message}`;errors.textContent=`Сохранение не выполнено: ${error.message} (${error.status||'network'}, request ${error.requestId||'нет'})`}}
async function refreshSavedPlans(){try{const data=await apiFetch('/api/plans');savedPlans.innerHTML=data.plans.map(p=>`<button data-id="${p.plan_id}">${p.plan_name||'Без названия'} · ${p.raid_format}/${p.target_size}</button>`).join('')||'<span class="muted">Планов нет</span>'}catch(error){savedPlans.innerHTML=`<span class="errors">${error.message}</span>`}}
async function openSavedPlan(id){status.textContent='Открытие...';try{const p=await apiFetch(`/api/plans/${id}`);currentPlanId=p.plan_id;planName.value=p.plan_name;raidDate.value=p.raid_date||'';boss.value=p.boss_id||'';format.value=p.raid_format;target.value=p.target_size;[...tbody.rows].forEach(r=>{const s=p.slots.find(x=>x.slot_no===Number(r.dataset.slot))||{};r.querySelector('.player').value=s.player_name||'';r.querySelector('.class').innerHTML=classOptions(s.class_code||'');syncSpecs(r,s.class_code||'',s.spec_code||'');r.querySelector('.locked').checked=!!s.locked});syncFormat();status.textContent=`Открыт: ${p.plan_id.slice(0,8)}`}catch(error){status.textContent=`Ошибка открытия: ${error.message}`}}
async function removeCurrentPlan(){if(!currentPlanId){status.textContent='Нет открытого плана';return}const deleting=currentPlanId;status.textContent='Удаление...';try{await apiFetch(`/api/plans/${deleting}`,{method:'DELETE'});clearCurrentPlan();await refreshSavedPlans();status.textContent=`Удалён: ${deleting.slice(0,8)}`}catch(error){status.textContent=`Ошибка удаления: ${error.message}`}}
format.addEventListener('change',syncFormat);target.addEventListener('input',schedule);tbody.addEventListener('input',schedule);tbody.addEventListener('change',e=>{const r=e.target.closest('tr');if(e.target.classList.contains('class'))syncSpecs(r,e.target.value);if(e.target.classList.contains('spec'))syncSpecs(r,r.querySelector('.class').value,e.target.value);schedule()});savedPlans.addEventListener('click',e=>{const b=e.target.closest('button[data-id]');if(b)openSavedPlan(b.dataset.id)});document.getElementById('newPlanButton').addEventListener('click',clearCurrentPlan);document.getElementById('savePlanButton').addEventListener('click',persistCurrentPlan);document.getElementById('deletePlanButton').addEventListener('click',removeCurrentPlan);
(async()=>{try{await loadCatalog();clearCurrentPlan();await refreshSavedPlans()}catch(error){status.textContent=`Ошибка запуска: ${error.message}`;logDiagnostic('Инициализация не выполнена',error.payload||String(error))}})();
</script></body></html>'''
